"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { useDevControls } from "@/hooks/useDevControls";
import {
  ANIMATION_DURATION_MS,
  CANVAS_SIZE,
  generateSequencePaths,
} from "./data";
import { useImageSequence } from "./hooks/useImageSequence";
import { useMorphAnimation } from "./hooks/useMorphAnimation";
import { MorphCanvas } from "./MorphCanvas";
import { Switcher } from "./Switcher";
import "./styles.css";

export default function LumaMorphing() {
  const [isDebug, setIsDebug] = useState(false);

  useEffect(() => {
    setIsDebug(new URLSearchParams(window.location.search).has("debug"));
  }, []);

  const { duration, resolution, showFrameIndex } = useDevControls(
    "Morph Controls",
    {
      duration: { value: ANIMATION_DURATION_MS, min: 100, max: 3000, step: 50 },
      resolution: { value: CANVAS_SIZE, options: [360, 720, 1080, 1440] },
      showFrameIndex: { value: false },
    }
  );

  const [reducedMotion, setReducedMotion] = useState(false);
  useEffect(() => {
    const mq = window.matchMedia("(prefers-reduced-motion: reduce)");
    setReducedMotion(mq.matches);
    const handler = (e: MediaQueryListEvent) => setReducedMotion(e.matches);
    mq.addEventListener("change", handler);
    return () => mq.removeEventListener("change", handler);
  }, []);

  const paths = useMemo(() => generateSequencePaths(), []);
  const { images, loaded, loadProgress } = useImageSequence(paths, isDebug);

  const { progressRef, animateTo } = useMorphAnimation({
    duration,
    reducedMotion,
    debug: isDebug,
  });

  const [activePersona, setActivePersona] = useState(1);

  const handleSelect = useCallback(
    (target: number) => {
      setActivePersona(target);
      animateTo(target);
    },
    [animateTo]
  );

  useEffect(() => {
    function handleKeyDown(e: KeyboardEvent) {
      if (e.key === "ArrowRight" || e.key === "ArrowDown") {
        e.preventDefault();
        const next = activePersona >= 4 ? 1 : activePersona + 1;
        handleSelect(next);
      } else if (e.key === "ArrowLeft" || e.key === "ArrowUp") {
        e.preventDefault();
        const prev = activePersona <= 1 ? 4 : activePersona - 1;
        handleSelect(prev);
      }
    }

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [activePersona, handleSelect]);

  if (!loaded) {
    return (
      <div className="luma-morphing-loading">
        <div className="luma-morphing-loading-bar">
          <div
            className="luma-morphing-loading-fill"
            style={{ transform: `scaleX(${loadProgress})` }}
          />
        </div>
        <span className="luma-morphing-loading-text">
          {Math.round(loadProgress * 100)}%
        </span>
      </div>
    );
  }

  return (
    <div className="luma-morphing-content">
      <div className="luma-morphing-canvas-wrapper">
        <MorphCanvas
          images={images}
          progressRef={progressRef}
          resolution={resolution}
          showFrameIndex={showFrameIndex}
          debug={isDebug}
        />
        <div className="luma-morphing-vignette" aria-hidden />
      </div>
      <Switcher activePersona={activePersona} onSelect={handleSelect} />
    </div>
  );
}

"use client";

import { useCallback, useEffect, useRef, useState } from "react";

interface UseImageSequenceResult {
  images: HTMLImageElement[];
  loaded: boolean;
  /** 0-1 fraction of images loaded so far */
  loadProgress: number;
}

export function useImageSequence(
  paths: string[],
  debug = false
): UseImageSequenceResult {
  const [loaded, setLoaded] = useState(false);
  const [loadProgress, setLoadProgress] = useState(0);
  const imagesRef = useRef<HTMLImageElement[]>([]);

  const logDebug = useCallback(
    (msg: string) => {
      if (debug) {
        console.log(`[luma-morphing] ${msg}`);
      }
    },
    [debug]
  );

  useEffect(() => {
    let cancelled = false;
    const total = paths.length;
    let loadedCount = 0;
    let lastReportedPct = -1;

    const imagePromises = paths.map(
      (src) =>
        new Promise<HTMLImageElement>((resolve) => {
          const img = new Image();
          img.src = src;
          img.onload = () => {
            loadedCount++;
            const pct = Math.floor((loadedCount / total) * 10) * 10;
            if (!cancelled) {
              setLoadProgress(loadedCount / total);
              if (pct > lastReportedPct) {
                lastReportedPct = pct;
                logDebug(`preload: ${pct}% (${loadedCount}/${total})`);
              }
            }
            resolve(img);
          };
          img.onerror = () => {
            logDebug(`failed to load: ${src}`);
            loadedCount++;
            if (!cancelled) {
              setLoadProgress(loadedCount / total);
            }
            resolve(img);
          };
        })
    );

    Promise.all(imagePromises).then((imgs) => {
      if (cancelled) {
        return;
      }
      imagesRef.current = imgs;
      setLoaded(true);
      logDebug("all images loaded");
    });

    return () => {
      cancelled = true;
    };
  }, [paths, logDebug]);

  return { images: imagesRef.current, loaded, loadProgress };
}

"use client";

import { useCallback, useEffect, useRef } from "react";
import {
  ANIMATION_DURATION_MS,
  calculateShortestPath,
  SEQUENCE_COUNT,
} from "../data";

interface UseMorphAnimationOptions {
  duration?: number;
  reducedMotion?: boolean;
  debug?: boolean;
}

interface UseMorphAnimationResult {
  progressRef: React.RefObject<number>;
  animateTo: (target: number) => void;
}

export function useMorphAnimation(
  options: UseMorphAnimationOptions = {}
): UseMorphAnimationResult {
  const {
    duration = ANIMATION_DURATION_MS,
    reducedMotion = false,
    debug = false,
  } = options;

  const progressRef = useRef(1);
  const rafRef = useRef<number | null>(null);
  const startTimeRef = useRef<number | null>(null);
  const startValueRef = useRef(1);
  const targetValueRef = useRef(1);

  const logDebug = useCallback(
    (msg: string) => {
      if (debug) {
        console.log(`[luma-morphing] ${msg}`);
      }
    },
    [debug]
  );

  const animateTo = useCallback(
    (target: number) => {
      if (rafRef.current !== null) {
        cancelAnimationFrame(rafRef.current);
      }

      const diff = calculateShortestPath(progressRef.current, target);
      logDebug(
        `morph: ${progressRef.current.toFixed(2)} -> ${target} (shortest path: ${diff > 0 ? "+" : ""}${diff.toFixed(2)}, duration: ${duration}ms)`
      );

      if (reducedMotion) {
        progressRef.current = target;
        return;
      }

      startTimeRef.current = null;
      startValueRef.current = progressRef.current;
      targetValueRef.current = target;

      const animate = (timestamp: number) => {
        if (startTimeRef.current === null) {
          startTimeRef.current = timestamp;
        }

        const elapsed = timestamp - startTimeRef.current;

        if (elapsed < duration) {
          const t = elapsed / duration;
          const diff = calculateShortestPath(
            startValueRef.current,
            targetValueRef.current
          );
          let newValue = startValueRef.current + diff * t;

          if (newValue > SEQUENCE_COUNT) {
            newValue -= SEQUENCE_COUNT;
          }
          if (newValue < 1) {
            newValue += SEQUENCE_COUNT;
          }

          progressRef.current = newValue;
          rafRef.current = requestAnimationFrame(animate);
        } else {
          progressRef.current = targetValueRef.current;
          rafRef.current = null;
          startTimeRef.current = null;
        }
      };

      rafRef.current = requestAnimationFrame(animate);
    },
    [duration, reducedMotion, logDebug]
  );

  useEffect(() => {
    return () => {
      if (rafRef.current !== null) {
        cancelAnimationFrame(rafRef.current);
      }
    };
  }, []);

  return { progressRef, animateTo };
}

"use client";

import { useEffect, useRef } from "react";
import { CANVAS_SIZE, progressToIndex } from "./data";

interface MorphCanvasProps {
  images: HTMLImageElement[];
  progressRef: React.RefObject<number>;
  resolution?: number;
  showFrameIndex?: boolean;
  debug?: boolean;
}

export function MorphCanvas({
  images,
  progressRef,
  resolution = CANVAS_SIZE,
  showFrameIndex = false,
  debug = false,
}: MorphCanvasProps) {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const currentIndexRef = useRef(-1);
  const rafRef = useRef<number | null>(null);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || images.length === 0) {
      return;
    }

    const dpr = Math.min(window.devicePixelRatio, 2);
    canvas.width = resolution * dpr;
    canvas.height = resolution * dpr;
    canvas.style.width = `${resolution}px`;
    canvas.style.height = `${resolution}px`;

    const ctx = canvas.getContext("2d");
    if (!ctx) {
      return;
    }

    ctx.scale(dpr, dpr);

    function render() {
      const index = progressToIndex(progressRef.current);

      if (index !== currentIndexRef.current) {
        currentIndexRef.current = index;
        const img = images[index];

        if (ctx && img?.complete && img.naturalWidth > 0) {
          ctx.drawImage(img, 0, 0, resolution, resolution);
        }

        if (showFrameIndex && ctx) {
          ctx.fillStyle = "rgba(0, 0, 0, 0.5)";
          ctx.fillRect(0, 0, 60, 28);
          ctx.fillStyle = "#fff";
          ctx.font = "14px monospace";
          ctx.fillText(`#${index}`, 8, 20);
        }

        if (debug) {
          console.log(
            `[luma-morphing] frame: ${index}, progress: ${progressRef.current.toFixed(3)}`
          );
        }
      }

      rafRef.current = requestAnimationFrame(render);
    }

    rafRef.current = requestAnimationFrame(render);

    return () => {
      if (rafRef.current !== null) {
        cancelAnimationFrame(rafRef.current);
      }
    };
  }, [images, progressRef, resolution, showFrameIndex, debug]);

  return (
    <canvas
      ref={canvasRef}
      className="luma-morphing-canvas"
      aria-label="Morphing image sequence canvas"
    />
  );
}

"use client";

import { PERSONAS } from "./data";

interface SwitcherProps {
  activePersona: number;
  onSelect: (target: number) => void;
}

export function Switcher({ activePersona, onSelect }: SwitcherProps) {
  return (
    <div className="luma-morphing-switcher-container">
      <div
        className="luma-morphing-switcher"
        role="group"
        aria-label="Persona selector"
      >
        {PERSONAS.map((label, i) => {
          const value = i + 1;
          const isActive = activePersona === value;

          return (
            <div key={value} className="luma-morphing-button-wrapper">
              <button
                type="button"
                className={`luma-morphing-button ${isActive ? "luma-morphing-button--active" : ""}`}
                data-state={value}
                onClick={() => onSelect(value)}
                aria-current={isActive ? "true" : undefined}
                aria-label={`Persona ${label}`}
              />
              <span className="luma-morphing-button-label">{label}</span>
            </div>
          );
        })}
      </div>
    </div>
  );
}

export const SEQUENCE_COUNT = 4;
export const FRAMES_PER_SEQUENCE = 24;
export const TOTAL_FRAMES = SEQUENCE_COUNT * FRAMES_PER_SEQUENCE;
export const CANVAS_SIZE = 720;
export const ANIMATION_DURATION_MS = 1000;

export const PERSONAS = ["1", "2", "3", "4"] as const;

const SEQUENCE_PAIRS = [
  [1, 2],
  [2, 3],
  [3, 4],
  [4, 1],
] as const;

/** Folder mapping: new 1→2 uses old 3→4, new 2→3 uses old 4→1, etc. (3→1, 4→2, 1→3, 2→4) */
const SEQUENCE_FOLDERS: [number, number][] = [
  [3, 4], // new 1-2
  [4, 1], // new 2-3
  [1, 2], // new 3-4
  [2, 3], // new 4-1
];

export function generateSequencePaths(): string[] {
  const paths: string[] = [];
  const cacheBust = typeof window !== "undefined" ? `?v=${Date.now()}` : "";

  for (const [from, to] of SEQUENCE_FOLDERS) {
    for (let i = 0; i < FRAMES_PER_SEQUENCE; i++) {
      const padded = i.toString().padStart(2, "0");
      paths.push(
        `https://www.razisyed.cv/experiments/luma-morphing/morphing/${from}-${to}/${from}-${to}${padded}.png${cacheBust}`
      );
    }
  }

  return paths;
}

/**
 * Normalize a value within [min, max] to [0, 1], clamped.
 */
export function normalize(value: number, min: number, max: number): number {
  return Math.max(0, Math.min(1, (value - min) / (max - min)));
}

/**
 * Find the shortest circular distance from `start` to `end`
 * on a ring of SEQUENCE_COUNT states (1-indexed, wrapping at SEQUENCE_COUNT).
 * Positive = forward, negative = backward.
 */
export function calculateShortestPath(start: number, end: number): number {
  const direct = end - start;
  const throughTop = end + SEQUENCE_COUNT - start;
  const throughBottom = end - (start + SEQUENCE_COUNT);

  const candidates = [direct, throughTop, throughBottom];
  const absValues = candidates.map(Math.abs);
  const minAbs = Math.min(...absValues);

  return candidates[absValues.indexOf(minAbs)];
}

/**
 * Map a progress value (1 to SEQUENCE_COUNT+1) to a frame index (0 to TOTAL_FRAMES-1).
 */
export function progressToIndex(progress: number): number {
  return Math.round(
    normalize(progress, 1, SEQUENCE_COUNT + 1) * (TOTAL_FRAMES - 1)
  );
}
